def _entry(model, title, singular, columns, search, form_fields, workflow=None, **extra):
    result = {
        "model": model,
        "title": title,
        "singular": singular,
        "columns": columns,
        "search": search,
        "form_fields": form_fields,
        "select_related": list(extra.pop("select_related", ())),
    }
    if workflow:
        result["workflow"] = workflow
    result.update(extra)
    return result


