def _document(line_model, relation, header_fields, line_fields, line_title, *, actions=None, totals=(), editable_statuses=None, line_select_related=(), fk_name=None):
    return {
        "line_model": line_model,
        "line_relation": relation,
        "header_fields": header_fields,
        "line_fields": line_fields,
        "line_title": line_title,
        "line_select_related": line_select_related,
        "total_fields": list(totals),
        "editable_statuses": editable_statuses,
        "actions": actions or {},
        "fk_name": fk_name,
    }


